  const res = await fetch(`/api/messages?roomId=${roomId}&limit=20`);
  const messages = await res.json();
  messages.forEach(msg => addMessage(msg));
}
```

### WebSocket Handling
```javascript
const ws = new WebSocket(`ws://api.example.com/chat/${roomId}`);
ws.onmessage = (event) => {
  const msg = JSON.parse(event.data);
  if (!seenIds.has(msg.id)) {
    seenIds.add(msg.id);
    addMessage(msg);
  }
};
```

### Service Worker Cache Strategy
```javascript
// sw.js
self.addEventListener('fetch', (e) => {
  if (e.request.url.includes('/api/messages')) {
    e.respondWith(
      caches.open('chat-cache').then(cache => 
        cache.match(e.request).then(res => res || fetch(e.request))
      )
    );
  }
