## Why This Is Asked
Tests ability to design a small data-layer primitive using closures, promises, and batching for performance.

## Key Concepts
- Closures and per-key caches
- Promise queuing and batch network calls
- TTL-based eviction and memory safety
- Error handling and cancellation tokens

## Code Example
```javascript
function createBatchingCache(fetcher, { batchDelay = 100, ttl = 5000 } = {}) {
  const cache = new Map(); // key -> { value, expiresAt }
  const inFlight = new Map(); // key -> { promise, resolve, reject }
  let batch = [];
  let timer = null;

  async function flush() {
    const keys = batch;
    batch = [];
    const uniq = Array.from(new Set(keys));
    try {
      const results = await fetcher(uniq);
      uniq.forEach((k, i) => {
        const v = results[i];
        cache.set(k, { value: v, expiresAt: Date.now() + ttl });
        if (inFlight.has(k)) inFlight.get(k).resolve(v);
        inFlight.delete(k);
      });
    } catch (e) {
      uniq.forEach(k => inFlight.get(k)?.reject(e));
      uniq.forEach(k => inFlight.delete(k));
    }
  }

  return {
    get(key) {
      const c = cache.get(key);
      if (c && c.expiresAt > Date.now()) return Promise.resolve(c.value);
      if (inFlight.has(key)) return inFlight.get(key).promise;
      let resolve, reject;
      const p = new Promise((res, rej) => { resolve = res; reject = rej; });
      inFlight.set(key, { promise: p, resolve, reject });
      batch.push(key);
      if (!timer) timer = setTimeout(() => { timer = null; flush(); }, batchDelay);
      return p;
    },
    clear() {
      cache.clear();
      inFlight.clear();
      batch = [];
      if (timer) clearTimeout(timer);
      timer = null;
    }
  };
}
```

## Why This Is Asked

This question tests the candidate's ability to implement proper tenant isolation in a React application, correctly utilize Context + useReducer to model a small Redux-like store, and implement basic form validation. It ensures the candidate can wire UI components with minimal boilerplate while maintaining clean architectural patterns.

## Key Concepts

- React hooks: useReducer, useContext, useMemo, and useCallback
- Context isolation per tenant with automatic state reset on tenant switch
- Reducer patterns for field operations (add, update, toggle required, move)
- Memoization for performance optimization
- Lightweight client-side validation

## Code Example

```javascript
const initialState = { fields: [] };

function formReducer(state, action) {
  switch (action.type) {
    case 'ADD_FIELD':
      return { ...state, fields: [...state.fields, action.payload] };
    case 'UPDATE_FIELD':
      return {
        ...state,
        fields: state.fields.map(f =>
          f.id === action.payload.id ? { ...f, ...action.payload } : f
        )
      };
    case 'TOGGLE_REQUIRED':
      return {
        ...state,
        fields: state.fields.map(f =>
          f.id === action.payload ? { ...f, required: !f.required } : f
        )
      };
    case 'MOVE_FIELD':
      const fields = [...state.fields];
      const [moved] = fields.splice(action.payload.fromIndex, 1);
      fields.splice(action.payload.toIndex, 0, moved);
      return { ...state, fields };
    default:
      return state;
  }
}

// TenantContext controls active tenant
const TenantContext = createContext(null);

// FormEditorContext holds the per-tenant form state
const FormEditorContext = createContext(null);

function FormEditorProvider({ children }) {
  const { tenantId } = useContext(TenantContext);
  const [state, dispatch] = useReducer(formReducer, initialState);

  // Reset state when tenant changes
  useEffect(() => {
    dispatch({ type: 'RESET' });
  }, [tenantId]);

  const validate = useCallback((fields) => {
    return fields.map(field => {
      const errors = [];
      if (field.required && !field.label) errors.push('Label is required');
      if (field.type === 'number') {
        if (field.min !== undefined && field.max !== undefined && field.min > field.max) {
          errors.push('Min cannot exceed max');
        }
      }
      return { fieldId: field.id, errors, isValid: errors.length === 0 };
    });
  }, []);

  return (
    <FormEditorContext.Provider value={{ state, dispatch, validate }}>
      {children}
    </FormEditorContext.Provider>
  );
}
```

## Why This Is Asked
This question evaluates understanding of closures, Promise deduplication, request cancellation, and caching strategies in building a production-ready fetch helper. It also touches on memory management with LRU caches and handling abortable requests.

## Key Concepts
- Closures for per-key state isolation
- Promise deduplication to prevent redundant network requests
- Cancellation with AbortController for stale requests
- LRU cache implementation using Map for ordered storage
- Edge cases: rapid toggling between keys and stale data handling

## Code Example
```javascript
const api = (() => {
  const inFlight = new Map();
  const cache = new Map();
  const MAX_CACHE = 50;

  function memoFetch(key, options = {}) {
    if (cache.has(key)) {
      const entry = cache.get(key);
      cache.delete(key);
      cache.set(key, entry);
      return Promise.resolve(entry);
    }

    if (inFlight.has(key)) {
      return inFlight.get(key);
    }

    const controller = new AbortController();
    const promise = fetch(key, { ...options, signal: controller.signal })
      .then(res => res.json())
      .then(data => {
        inFlight.delete(key);
        if (cache.size >= MAX_CACHE) {
          const firstKey = cache.keys().next().value;
          cache.delete(firstKey);
        }
        cache.set(key, data);
        return data;
      })
      .catch(err => {
        inFlight.delete(key);
        throw err;
      });

    inFlight.set(key, { promise, controller });
    return promise;
  }

  function cancel(key) {
    if (inFlight.has(key)) {
      inFlight.get(key).controller.abort();
      inFlight.delete(key);
    }
  }

  return { memoFetch, cancel };
})();
```

